from pathlib import Path

FILES=[Path('mobile.html'),Path('app base.html')]

BUTTON_ANCHOR='''    <div id="ffaAthleteSearchResults" style="display:none;margin-top:8px;border:1px solid var(--line);border-radius:10px;overflow:hidden"></div>'''
BUTTON_REPL=BUTTON_ANCHOR+'''\n    <button type="button" id="openFfaRanking" style="width:100%;margin-top:9px">Voir le classement complet</button>'''

CARD='''\n  <section class="card" id="ffaRankingCard" style="display:none;margin-bottom:12px">\n    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px">\n      <h2 style="margin:0;font-size:16px">Classement FFA complet</h2>\n      <button type="button" id="closeFfaRanking" style="padding:7px 10px;font-size:12px">Fermer</button>\n    </div>\n    <div style="display:flex;gap:6px;margin-bottom:8px">\n      <button type="button" class="ffaFullModeBtn" data-mode="general" style="flex:1;padding:8px 5px;font-size:12px">Général</button>\n      <button type="button" class="ffaFullModeBtn" data-mode="sex" style="flex:1;padding:8px 5px;font-size:12px">H/F</button>\n      <button type="button" class="ffaFullModeBtn" data-mode="category" style="flex:1;padding:8px 5px;font-size:12px">Catégorie</button>\n    </div>\n    <input id="ffaFullSearch" type="search" placeholder="Rechercher nom / prénom..." style="margin-bottom:8px">\n    <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:8px">\n      <select id="ffaFullSex" style="width:100%;padding:10px;border-radius:9px;border:1px solid var(--line);background:var(--panel2);color:var(--text)">\n        <option value="">Tous sexes</option><option value="M">Hommes</option><option value="F">Femmes</option>\n      </select>\n      <select id="ffaFullCategory" style="width:100%;padding:10px;border-radius:9px;border:1px solid var(--line);background:var(--panel2);color:var(--text)">\n        <option value="">Toutes catégories</option><option>CA</option><option>JU</option><option>ES</option><option>SE</option><option>M0</option><option>M1</option><option>M2</option><option>M3</option><option>M4</option><option>M5</option><option>M6</option><option>M7</option><option>M8</option><option>M9</option><option>M10</option>\n      </select>\n      <input id="ffaFullYear" inputmode="numeric" placeholder="Année naissance" style="width:100%;padding:10px;border-radius:9px;border:1px solid var(--line);background:var(--panel2);color:var(--text)">\n      <input id="ffaFullMaxPb" inputmode="numeric" placeholder="PB max, ex 35:00" style="width:100%;padding:10px;border-radius:9px;border:1px solid var(--line);background:var(--panel2);color:var(--text)">\n    </div>\n    <div id="ffaFullMsg" class="msg" style="margin:4px 0 8px"></div>\n    <div id="ffaFullResults" style="border:1px solid var(--line);border-radius:10px;overflow:hidden"></div>\n    <div style="display:flex;gap:6px;margin-top:8px">\n      <button type="button" id="ffaFullPrev" style="flex:1;padding:9px">Précédent</button>\n      <button type="button" id="ffaFullNext" style="flex:1;padding:9px">Suivant</button>\n    </div>\n  </section>\n'''

JS_ANCHOR='''const _ffaAthleteSearch=$("ffaAthleteSearch");'''
JS='''let ffaFullMode="sex";\nlet ffaFullPage=0;\nconst FFA_FULL_PAGE_SIZE=100;\nfunction parsePbLimit(v){\n  v=String(v||"").trim().replace("'",":").replace('"','');\n  if(!v) return null;\n  if(/^\\d+$/.test(v)) return Number(v)*60;\n  const m=v.match(/^(\\d{1,2})[:h](\\d{1,2})$/i);\n  return m ? Number(m[1])*60+Number(m[2]) : null;\n}\nfunction getFullRank(p){\n  return ffaFullMode==="general" ? ffaGeneralRank.get(p) : ffaFullMode==="category" ? ffaCategoryRank.get(p) : ffaSexRank.get(p);\n}\nfunction renderFullFfaRanking(resetPage=false){\n  if(resetPage) ffaFullPage=0;\n  const box=$("ffaFullResults"), msg=$("ffaFullMsg");\n  if(!box||!msg) return;\n  if(!ffaReady){ msg.textContent="Base FFA en cours de chargement…"; return; }\n  const q=norm($("ffaFullSearch").value||"");\n  const sex=$("ffaFullSex").value;\n  const cat=$("ffaFullCategory").value;\n  const year=String($("ffaFullYear").value||"").trim();\n  const maxPb=parsePbLimit($("ffaFullMaxPb").value);\n  let rows=ffa.filter(p=>{\n    if(!Number.isFinite(Number(p.pb_sec))) return false;\n    if(sex && p.sexe!==sex) return false;\n    if(cat && currentFfaCategory(p)!==cat) return false;\n    if(year && String(p.annee_naissance||"")!==year) return false;\n    if(maxPb!=null && Number(p.pb_sec)>maxPb) return false;\n    if(q){\n      const nk=p.name_key||nameKey(p.full_name||"");\n      const toks=q.split(" ").filter(Boolean);\n      if(!toks.every(t=>nk.includes(t))) return false;\n    }\n    return getFullRank(p)!=null;\n  });\n  rows.sort((a,b)=>{\n    const ra=getFullRank(a), rb=getFullRank(b);\n    return ra-rb || Number(a.pb_sec)-Number(b.pb_sec) || norm(a.full_name).localeCompare(norm(b.full_name));\n  });\n  const pages=Math.max(1,Math.ceil(rows.length/FFA_FULL_PAGE_SIZE));\n  if(ffaFullPage>=pages) ffaFullPage=pages-1;\n  const start=ffaFullPage*FFA_FULL_PAGE_SIZE;\n  const slice=rows.slice(start,start+FFA_FULL_PAGE_SIZE);\n  msg.textContent=rows.length.toLocaleString("fr-FR")+" athlète"+(rows.length>1?"s":"")+" · page "+(ffaFullPage+1)+"/"+pages;\n  box.innerHTML=slice.length ? slice.map(p=>{\n    const rank=getFullRank(p);\n    const rankText=rank===1?"1er":rank+"e";\n    const url=getFfaProfileUrl(p);\n    const catText=currentFfaCategory(p)+(p.sexe||"");\n    const scope=ffaFullMode==="category" ? catText : (p.sexe||"");\n    const link=url ? `<a href="${esc(url)}" target="_blank" rel="noopener" style="color:var(--accent);text-decoration:none;font-weight:700">${esc(p.full_name||"")}</a>` : `<b>${esc(p.full_name||"")}</b>`;\n    return `<div style="display:grid;grid-template-columns:54px minmax(0,1fr) 72px;gap:7px;align-items:center;padding:9px 10px;border-bottom:1px solid var(--line)"><div style="font-weight:800">${esc(rankText)}</div><div style="min-width:0"><div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${link}</div><div class="small">${esc([p.annee_naissance||"—",scope].filter(Boolean).join(" · "))}</div></div><div style="text-align:right;font-weight:800">${esc(p.pb_chrono||"—")}</div></div>`;\n  }).join("") : `<div class="msg" style="padding:12px">Aucun athlète avec ces filtres.</div>`;\n  $("ffaFullPrev").disabled=ffaFullPage<=0;\n  $("ffaFullNext").disabled=ffaFullPage>=pages-1;\n}\nfunction updateFullModeButtons(){\n  document.querySelectorAll(".ffaFullModeBtn").forEach(b=>{\n    const active=b.getAttribute("data-mode")===ffaFullMode;\n    b.style.background=active?"#2458a6":"";\n    b.style.borderColor=active?"#3973cf":"";\n  });\n}\nconst _openFfaRanking=$("openFfaRanking");\nif(_openFfaRanking) _openFfaRanking.addEventListener("click",()=>{\n  $("ffaRankingCard").style.display="block";\n  updateFullModeButtons();\n  renderFullFfaRanking(true);\n  $("ffaRankingCard").scrollIntoView({behavior:"smooth",block:"start"});\n});\nconst _closeFfaRanking=$("closeFfaRanking");\nif(_closeFfaRanking) _closeFfaRanking.addEventListener("click",()=>{$("ffaRankingCard").style.display="none";});\ndocument.querySelectorAll(".ffaFullModeBtn").forEach(b=>b.addEventListener("click",()=>{ffaFullMode=b.getAttribute("data-mode");updateFullModeButtons();renderFullFfaRanking(true);}));\n["ffaFullSearch","ffaFullSex","ffaFullCategory","ffaFullYear","ffaFullMaxPb"].forEach(id=>{const el=$(id);if(el) el.addEventListener(id==="ffaFullSearch"||id==="ffaFullYear"||id==="ffaFullMaxPb"?"input":"change",()=>renderFullFfaRanking(true));});\nconst _ffaFullPrev=$("ffaFullPrev"); if(_ffaFullPrev) _ffaFullPrev.addEventListener("click",()=>{if(ffaFullPage>0){ffaFullPage--;renderFullFfaRanking(false);}});\nconst _ffaFullNext=$("ffaFullNext"); if(_ffaFullNext) _ffaFullNext.addEventListener("click",()=>{ffaFullPage++;renderFullFfaRanking(false);});\n'''

for path in FILES:
    text=path.read_text(encoding='utf-8')
    if 'id="openFfaRanking"' in text:
        raise SystemExit(f'{path}: full ranking already installed')
    if BUTTON_ANCHOR not in text:
        raise SystemExit(f'{path}: search result anchor not found')
    text=text.replace(BUTTON_ANCHOR,BUTTON_REPL,1)
    # put the full card directly after the search card
    marker='''  </section>\n\n  <div class="card" id="restoreCard"'''
    if marker in text:
        text=text.replace(marker,'''  </section>'''+CARD+'''\n  <div class="card" id="restoreCard"''',1)
    else:
        marker='''  </section>\n\n  <div class="grid">'''
        if marker not in text:
            raise SystemExit(f'{path}: card insertion anchor not found')
        text=text.replace(marker,'''  </section>'''+CARD+'''\n  <div class="grid">''',1)
    if JS_ANCHOR not in text:
        raise SystemExit(f'{path}: JS anchor not found')
    text=text.replace(JS_ANCHOR,JS+JS_ANCHOR,1)
    path.write_text(text,encoding='utf-8')
